<div class="admin-page-heading"><div><span class="admin-eyebrow">CONTACT INBOX</span><p>Messages sent through the public website contact form.</p></div></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>SENDER</th><th>EMAIL</th><th>SUBJECT</th><th>STATUS</th><th>RECEIVED</th><th></th></tr></thead><tbody><?php foreach($messages as $item): ?><tr><td><strong><?= e($item['full_name']) ?></strong><small><?= e($item['phone']??'') ?></small></td><td><?= e($item['email']) ?></td><td><?= e($item['subject']?:'General enquiry') ?></td><td><span class="status <?= $item['is_read']?'status-completed':'status-pending' ?>"><?= $item['is_read']?'Read':'New' ?></span></td><td><?= e(format_date($item['created_at'])) ?></td><td><a class="table-action" href="<?= e(url('/admin/messages/'.$item['id'])) ?>">Open ↗</a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$messages): ?><div class="admin-empty"><span>✉</span><h3>Your inbox is clear</h3><p>Messages submitted through the contact form will appear here.</p></div><?php endif; ?></section>
